<span class="line"><span class="__shiki_140thh">    redisTemplate.</span><span class="__shiki_1t8gfj">opsForValue</span><span class="__shiki_140thh">().</span><span class="__shiki_1t8gfj">set</span><span class="__shiki_140thh">(key, value, actualExpire, TimeUnit.SECONDS);</span></span>
